【2】覚えること
・急性期＝高ウイルス量、インフルエンザ様症状
・無症候期＝見かけ上安定してもウイルス増殖は継続
・進行期＝CD4数低下、体重減少、慢性下痢など
・AIDS期＝日和見感染症・指標悪性腫瘍

